{
 "name": "open_view",
 "description": "Open a new view (pane) and make it active. `cells`: 'focus' (default: follow the focus), 'all', a cell id or a group reference. Genome views take `rows` (top to bottom): {kind:'track', track, cells?} or {kind:'distance', cells?, stat?} or {kind:'contacts', source, cells?} or {kind:'intervals', key}. Stats views take `stats` (rg | scaling | hist | scatter), `compare_groups` (group references overlaid), `field_x` / `field_y` (cell fields for hist / scatter). Embedding views take `embedding` (a cellm key). Returns {pane}.",
 "inputSchema": {
  "type": "object",
  "required": [
   "type"
  ],
  "properties": {
   "type": {
    "type": "string",
    "enum": [
     "3d",
     "embedding",
     "genome",
     "matrix",
     "stats"
    ]
   },
   "cells": {
    "type": "string"
   },
   "title": {
    "type": "string"
   },
   "rows": {
    "type": "array",
    "items": {
     "type": "object"
    }
   },
   "stats": {
    "type": "string",
    "enum": [
     "rg",
     "scaling",
     "hist",
     "scatter"
    ]
   },
   "compare_groups": {
    "type": "array",
    "items": {
     "type": "string"
    }
   },
   "field_x": {
    "type": "string"
   },
   "field_y": {
    "type": "string"
   },
   "embedding": {
    "type": "string"
   },
   "source": {
    "type": "string",
    "description": "matrix view: a contact-map key or 'distance'"
   }
  }
 }
}
{
 "name": "color_by",
 "description": "Colour all cells by a cell field (e.g. cell_type, rna.Nanog, if.H3K9me3).",
 "inputSchema": {
  "type": "object",
  "required": [
   "field"
  ],
  "properties": {
   "field": {
    "type": "string"
   }
  }
 }
}

